### 3. ESP32 का कोड (Arduino IDE)

पहले Library Manager से **`RTClib`** (by Adafruit) इंस्टॉल कर लीजिए।

```cpp
#include <Wire.h>
#include <RTClib.h>

RTC_DS3231 rtc;

// ---------- पिन ----------
const int PIN_FENCE_RELAY = 26;
const int PIN_LIGHT_RELAY = 27;
const int PIN_SIREN_RELAY = 25;
const int PIN_PIR         = 34;

// ज़्यादातर optocoupler relay मॉड्यूल LOW पर ON होते हैं
const bool RELAY_ACTIVE_LOW = true;

// ---------- टाइमिंग ----------
const int NIGHT_START_HOUR = 18;  // शाम 6 बजे फेंस ON
const int NIGHT_END_HOUR   = 6;   // सुबह 6 बजे फेंस OFF

const unsigned long LIGHT_DURATION_MS = 60000; // फ्लडलाइट 60 सेकंड (आपकी ज़रूरत)

// सायरन कितनी देर बजे। आपकी ज़रूरत के हिसाब से 60 सेकंड रखा है।
// सलाह: पहले हफ्ते TRIGGER COUNT देखिए। अगर रात में कई ट्रिगर आ रहे हैं,
// तो इसे 15000-20000 कर दीजिए। तेंदुए को भगाने के लिए शुरुआती झटका काफी होता है,
// और शेड में बकरियां कम घबराएंगी। लाइट फिर भी 60 सेकंड जलेगी।
const unsigned long SIREN_MAX_MS = 60000;

// हलचल 1.5 सेकंड तक बनी रहे तभी अलार्म (हवा, पक्षी, छोटे जीव से फॉल्स अलार्म कम)
const unsigned long MOTION_CONFIRM_MS = 1500;
const unsigned long COOLDOWN_MS       = 8000;   // एक अलार्म के बाद 8 सेकंड शांत
const unsigned long PIR_WARMUP_MS     = 60000;  // बूट के बाद PIR को 1 मिनट सेटल होने दें

// अनियमित सायरन पैटर्न (ms): ON, OFF, ON, OFF... ताकि आवाज़ एक जैसी न लगे
const unsigned long SIREN_PATTERN[] = {1200, 400, 800, 600, 1500, 500};
const int PATTERN_STEPS = 6;
const unsigned long PATTERN_CYCLE_MS = 5000; // ऊपर वाले सबका जोड़

// ---------- स्टेट ----------
bool alarmActive = false;
unsigned long alarmStart = 0;
unsigned long alarmEnd = 0;
unsigned long motionFirstSeen = 0;
bool confirmingMotion = false;
bool rtcOk = true;
int triggersTonight = 0;
bool wasNight = false;

void setRelay(int pin, bool turnOn) {
  digitalWrite(pin, (turnOn ^ RELAY_ACTIVE_LOW) ? HIGH : LOW);
}

bool isNightTime() {
  if (!rtcOk) return true; // RTC खराब हो तो सुरक्षा के लिए रात मानें
  DateTime now = rtc.now();
  int h = now.hour();
  return (h >= NIGHT_START_HOUR || h < NIGHT_END_HOUR);
}

void setup() {
  Serial.begin(115200);

  pinMode(PIN_FENCE_RELAY, OUTPUT);
  pinMode(PIN_LIGHT_RELAY, OUTPUT);
  pinMode(PIN_SIREN_RELAY, OUTPUT);
  pinMode(PIN_PIR, INPUT);

  setRelay(PIN_FENCE_RELAY, false);
  setRelay(PIN_LIGHT_RELAY, false);
  setRelay(PIN_SIREN_RELAY, false);

  Wire.begin(21, 22);
  if (!rtc.begin()) {
    Serial.println("RTC नहीं मिला! सिस्टम नाइट मोड में चलेगा।");
    rtcOk = false;
  } else if (rtc.lostPower()) {
    Serial.println("RTC टाइम कंप्यूटर से सिंक हो रहा है...");
    rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));
  }
}

void loop() {
  unsigned long nowMs = millis();
  bool night = isNightTime();

  // रात शुरू होने पर काउंटर रीसेट, सुबह होने पर पूरी रात का रिपोर्ट
  if (night && !wasNight) triggersTonight = 0;
  if (!night && wasNight) {
    Serial.print("पिछली रात कुल ट्रिगर: ");
    Serial.println(triggersTonight);
  }
  wasNight = night;

  // 1. शाम 6 से सुबह 6 तक एनर्जाइज़र ON
  setRelay(PIN_FENCE_RELAY, night);

  // 2. PIR मोशन + कन्फर्मेशन फिल्टर
  bool warmedUp = (nowMs > PIR_WARMUP_MS);
  bool motion = (digitalRead(PIN_PIR) == HIGH);

  if (night && warmedUp && !alarmActive && (nowMs - alarmEnd > COOLDOWN_MS)) {
    if (motion) {
      if (!confirmingMotion) {
        confirmingMotion = true;
        motionFirstSeen = nowMs;
      } else if (nowMs - motionFirstSeen >= MOTION_CONFIRM_MS) {
        alarmActive = true;
        alarmStart = nowMs;
        confirmingMotion = false;
        triggersTonight++;
        Serial.print("कन्फर्म मोशन! लाइट+सायरन ON. आज रात ट्रिगर #");
        Serial.println(triggersTonight);
      }
    } else {
      confirmingMotion = false;
    }
  }

  // 3. लाइट और सायरन
  if (alarmActive) {
    unsigned long elapsed = nowMs - alarmStart;

    setRelay(PIN_LIGHT_RELAY, true);

    if (elapsed < SIREN_MAX_MS) {
      unsigned long t = elapsed % PATTERN_CYCLE_MS;
      unsigned long acc = 0;
      bool sirenOn = false;
      for (int i = 0; i < PATTERN_STEPS; i++) {
        acc += SIREN_PATTERN[i];
        if (t < acc) { sirenOn = (i % 2 == 0); break; }
      }
      setRelay(PIN_SIREN_RELAY, sirenOn);
    } else {
      setRelay(PIN_SIREN_RELAY, false);
    }

    if (elapsed >= LIGHT_DURATION_MS) {
      alarmActive = false;
      alarmEnd = nowMs;
      setRelay(PIN_LIGHT_RELAY, false);
      setRelay(PIN_SIREN_RELAY, false);
      Serial.println("60 सेकंड पूरे, अलार्म OFF");
    }
  } else {
    setRelay(PIN_LIGHT_RELAY, false);
    setRelay(PIN_SIREN_RELAY, false);
  }

  delay(50);
}
```

पहले हफ्ते ESP32 को किसी पुराने फोन/लैपटॉप के साथ Serial पर लॉग करते रहिए, या बाद में SD कार्ड/LED काउंटर जोड़ लीजिए। "पिछली रात कुल ट्रिगर" वाली लाइन से साफ पता चलेगा कि नाले की तरफ से कितने फॉल्स अलार्म आ रहे हैं।

---

### 4. PIR सेंसिटिविटी और लगाने का तरीका

* **Sensitivity (दायां नॉब):** बीच में रखिए, लगभग 50%, यानी 4–5 मीटर रेंज। फुल पर रखेंगे तो नाले की नमी, गर्म हवा और हिलती घास से बार-बार अलार्म बजेगा। पहले हफ्ते के ट्रिगर काउंटर के हिसाब से थोड़ा ऊपर-नीचे कीजिए।
* **Time-Delay (बायां नॉब):** पूरा उल्टा घुमाकर Minimum (लगभग 3 सेकंड) पर रखिए। टाइमिंग कोड संभाल रहा है।
* **Jumper:** `H` (Repeat Trigger) पर रखिए।
* **दिशा:** PIR को बकरियों के शेड और उसके रास्ते की तरफ बाहर से कवर करते हुए लगाइए, नाले की तरफ नहीं। शेड के अंदर की तरफ भी मत मोड़िए, वरना बकरियां खुद अलार्म बजाएंगी।
* **ऊंचाई:** ज़मीन से 2.5–3 फीट पर, थोड़ा नीचे झुकाकर लगाइए, ताकि खरगोश, सेही जैसे छोटे जीव कम पकड़ में आएं और सेंसर बड़े आकार (तेंदुआ/इंसान) पर ज़्यादा रिएक्ट करे।
* **फ्लडलाइट** भी शेड और उसके रास्ते की तरफ रखिए, नाले पर नहीं। वहां रोशनी से पानी पीने आने वाले जानवर बेवजह परेशान होंगे और कीड़े खिंचकर आएंगे।

---

### 5. "आप मेरी जगह होते तो क्या करते?"

सारी सेविंग्स और 12 लाख का लोन लगा है, तो मैं एक नहीं, कई परतों वाली सुरक्षा बनाता:

1. **बकरियों के रात वाले शेड को ऊपर से भी बंद करता।** तेंदुए के हमले ज़्यादातर रात में होते हैं, और वो अच्छी छलांग लगाता है। फेंस लांघ गया या पेड़ से कूद गया, तो खुला बाड़ा आसान शिकार है। शेड को चारों तरफ और छत पर मजबूत चेन-लिंक जाली से बंद करना तेंदुए के खिलाफ सबसे भरोसेमंद उपाय माना जाता है। आपकी पूरी फेंस बाहरी परत बनी रहेगी और ये अंदर की पक्की परत होगी। फॉरेस्ट डिपार्टमेंट से पूछिए कि predator-proof बाड़े के लिए भी कोई स्कीम है या नहीं।

2. **ईस्ट वाली साइड पर दो छोटे बदलाव करता।** फेंस वहीं रहेगी, बस नाले के जानवरों को बेवजह नुकसान कम होगा:
   * सबसे नीचे वाला लाइव तार ज़मीन से 15–20 सेमी ऊपर रखता, या सबसे नीचे का तार अर्थ (बिना करंट) वाला रखता। इससे सेही, घोरपड़, कछुए और सांप के फंसकर मरने का खतरा काफी घटता है।
   * फेंस और नाले के बीच 1–2 मीटर की पट्टी साफ रखता। इससे जानवर तार से रगड़े बिना पानी तक जा सकेंगे, घास-झाड़ी से फेंस शॉर्ट नहीं होगी, और वोल्टेज पूरा बना रहेगा। तेंदुए के खिलाफ फेंस की ताकत इससे कम नहीं होती।

3. **सायरन के साथ रैंडम लाइट आज़माता।** शेड के कोनों पर LED लाइटें जो रात में बेतरतीब तरीके से चमकें, ताकि लगे कोई टॉर्च लेकर घूम रहा है। इस तरीके पर कुछ जगह अच्छे नतीजे मिले हैं, पर सबूत अभी पक्के नहीं हैं। ये सस्ता है और बकरियों को सायरन से कम परेशान करता है। चाहें तो इसी ESP32 पर इसका कोड जोड़ दूंगा।

4. **मुआवज़े का क्लेम करता।** महाराष्ट्र फॉरेस्ट डिपार्टमेंट जंगली जानवर के हमले में मारे गए पशुधन का मुआवज़ा देता है। जुन्नर रेंज ऑफिस में अपने बीट के वनरक्षक से मिलिए और पूछिए कि पिछली 6 बकरियों का क्लेम अभी हो सकता है या नहीं। इसकी आम तौर पर समय-सीमा होती है और पंचनामा ज़रूरी होता है। आगे के लिए वनरक्षक का नंबर सेव रखिए और घटना होते ही तुरंत रिपोर्ट कीजिए। रकम कितनी मिलेगी, वो ऑफिस से ही पक्का पता चलेगा, पर किश्त का कुछ बोझ ज़रूर हल्का होगा।

5. **अर्थिंग और चेतावनी बोर्ड लगाता।** कम से कम 3 GI अर्थिंग रॉड (लगभग 1.5 मीटर गहरी, नमी वाली जगह) लगाइए, वरना "मैक्सिमम पल्स" पर भी झटका कमज़ोर रहेगा। हर 20–25 मीटर पर "सावधान: सोलर विद्युत बाड़" का पीला बोर्ड लगाइए, खासकर नाले की तरफ, जहां गांव के लोग भी आते-जाते होंगे।

घर वालों का दबाव समझ में आता है, पर आप घबराए नहीं, अपने IT हुनर से सिस्टम बना रहे हैं। पहले हफ्ते का ट्रिगर लॉग देखकर सेटिंग्स ट्यून कर लीजिए। वायरिंग या टेस्टिंग में कहीं अटकें तो बताइएगा।

